const fs = require('fs-extra');
const path = require('path');
const os = require('os');

const {
  checkContext,
  stripGenerated,
  findPathRefs,
  findSkillRefs,
  alwaysLoadedLines,
} = require('../../lib/utils/context-check');

const MARKER =
  '<!-- Generated by ContextKit (@nolrm/contextkit) https://www.npmjs.com/package/@nolrm/contextkit -->';
const MARKER_END = '<!-- End ContextKit -->';

describe('context-check', () => {
  let tmpDir;

  beforeEach(async () => {
    tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'contextkit-context-check-'));
  });

  afterEach(async () => {
    await fs.remove(tmpDir);
  });

  it('1. finds .contextkit path references', () => {
    expect(findPathRefs('Read `.contextkit/standards/testing.md`, then go.')).toEqual([
      '.contextkit/standards/testing.md',
    ]);
  });

  it('2. finds `name` skill references', () => {
    expect(findSkillRefs('testing.md (`squad-test` skill), and the `/goal` skill')).toEqual([
      'squad-test',
      'goal',
    ]);
  });

  it('3. strips ContextKit-generated blocks', () => {
    const content = `before\n${MARKER}\ngenerated\n${MARKER_END}\nafter`;
    expect(stripGenerated(content)).toBe('before\n\nafter');
  });

  it('4. reports a missing file referenced from a bridge file', async () => {
    await fs.writeFile(path.join(tmpDir, 'AGENTS.md'), 'See `.contextkit/standards/gone.md`.\n');
    const warnings = await checkContext({ cwd: tmpDir });
    expect(warnings).toEqual(['AGENTS.md points to a missing file: .contextkit/standards/gone.md']);
  });

  it('5. ignores references inside ContextKit-generated blocks', async () => {
    await fs.writeFile(
      path.join(tmpDir, 'CLAUDE.md'),
      `${MARKER}\nSee \`.contextkit/standards/gone.md\` (\`squad-test\` skill)\n${MARKER_END}\n`
    );
    expect(await checkContext({ cwd: tmpDir })).toEqual([]);
  });

  it('6. flags removed skills referenced in user-owned standards', async () => {
    await fs.ensureDir(path.join(tmpDir, '.contextkit/standards'));
    await fs.writeFile(
      path.join(tmpDir, '.contextkit/standards/testing.md'),
      'Run the `review` skill before merging.\n'
    );
    const warnings = await checkContext({ cwd: tmpDir });
    expect(warnings[0]).toContain('removed `review` skill');
  });

  it('7. skips generated contextkit-* rule files', async () => {
    await fs.ensureDir(path.join(tmpDir, '.claude/rules'));
    await fs.writeFile(
      path.join(tmpDir, '.claude/rules/contextkit-standards.md'),
      '---\npaths:\n  - "x"\n---\nSee `.contextkit/missing.md`\n'
    );
    expect(await checkContext({ cwd: tmpDir })).toEqual([]);
  });

  it('8. counts always-loaded lines including @imports and unscoped rules', async () => {
    await fs.writeFile(path.join(tmpDir, 'CLAUDE.md'), '@AGENTS.md\n');
    await fs.writeFile(path.join(tmpDir, 'AGENTS.md'), 'a\nb\nc\n');
    await fs.ensureDir(path.join(tmpDir, '.claude/rules'));
    await fs.writeFile(path.join(tmpDir, '.claude/rules/always.md'), 'x\ny\n');
    await fs.writeFile(
      path.join(tmpDir, '.claude/rules/scoped.md'),
      '---\npaths:\n  - "src/**"\n---\nz\n'
    );
    // CLAUDE.md (2) + AGENTS.md (4) + always.md (3); scoped.md excluded
    expect(await alwaysLoadedLines(tmpDir)).toBe(9);
  });

  it('9. warns when always-loaded context exceeds the budget', async () => {
    await fs.writeFile(path.join(tmpDir, 'CLAUDE.md'), 'line\n'.repeat(20));
    const warnings = await checkContext({ cwd: tmpDir, budgetLines: 10 });
    expect(warnings[0]).toMatch(/Always-loaded context is 21 lines \(budget 10\)/);
  });
});
